def differenceOfDistinctValues(grid):
    m, n = len(grid), len(grid[0])
    res = [[0] * n for _ in range(m)]
    for r in range(m):
        for c in range(n):
            top = set(); i, j = r - 1, c - 1
            while i >= 0 and j >= 0:
                top.add(grid[i][j]); i -= 1; j -= 1
            bot = set(); i, j = r + 1, c + 1
            while i < m and j < n:
                bot.add(grid[i][j]); i += 1; j += 1
            res[r][c] = abs(len(top) - len(bot))
    return res
